package com.motionlayer
import android.os.Bundle
import androidx.activity.ComponentActivity; import androidx.activity.compose.setContent; import androidx.activity.viewModels
import androidx.compose.foundation.layout.*; import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.Modifier; import androidx.compose.ui.unit.dp
import com.motionlayer.data.ProjectRepository; import com.motionlayer.editor.*; import com.motionlayer.export.ExportScreen; import com.motionlayer.importer.ImportScreen; import com.motionlayer.ui.theme.MotionLayerTheme
class MainActivity:ComponentActivity(){ private val vm:EditorViewModel by viewModels(); override fun onCreate(b:Bundle?){ super.onCreate(b); setContent{ MotionLayerTheme{ var screen by remember{ mutableStateOf("home")}; when(screen){"home"->HomeScreen({screen="import"},{ id-> vm.loadProject(id); screen="editor"}); "import"->ImportScreen{uri,ratio->vm.createNewProject(uri,ratio); screen="editor"}; "editor"->EditorScreen(vm){screen="export"}; "export"->ExportScreen(vm.project.collectAsState().value) } } } } }
@Composable fun HomeScreen(onNew:()->Unit,onOpen:(String)->Unit){ val ctx= androidx.compose.ui.platform.LocalContext.current; val recent= remember{ ProjectRepository(ctx).recentProjects()}; Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement=Arrangement.spacedBy(16.dp)){ Text("MotionLayer", style=MaterialTheme.typography.displaySmall); Text("Advanced overlay motion editor for CapCut exports."); Button(onNew){Text("New Project")}; Text("Recent Projects"); recent.forEach{ p-> ElevatedCard(onClick={onOpen(p.projectId)}, modifier=Modifier.fillMaxWidth()){ Column(Modifier.padding(16.dp)){ Text(p.projectName); Text(p.canvas.ratio + " • " + p.layers.size + " layers") } } }; if(recent.isEmpty()) OutlinedButton(onNew){Text("Open Saved Project (none found)")} } }
